// Restarting forever hides a real fault. After a few attempts, stop trying and
// tell a human instead — a container that has died five times in a row is not
// going to be fixed by a sixth restart.
const MAX_RESTARTS = 5;

const inspected = $input.first().json;
const event = $('A container died').first().json;
const logs = $('Capture logs BEFORE restarting').first().json;

const restartCount = inspected.state?.restartCount ?? 0;
const logLines = (logs.logs ?? [])
  .map((l) => `[${l.stream}] ${l.message}`)
  .join('\n');

return [{
  json: {
    container: event.name,
    image: event.image ?? inspected.image ?? null,
    exitCode: event.attributes?.exitCode ?? null,
    diedAt: event.time ?? null,
    restartCount,
    giveUp: restartCount >= MAX_RESTARTS,
    logTail: logLines || '(no output captured)',
  },
}];
